<script>
  import { computeFairRegularizer } from '@/lib/formula-lessons/part4-models.mjs';
  export let lesson; export let spec; let delta=spec.delta;
  $: result=computeFairRegularizer({delta:Number(delta),x:spec.x,C:spec.C}); const f=(v,d=4)=>Number(v).toFixed(d);
  $: curve=Array.from({length:41},(_,i)=>-3+6*i/40).map(x=>({x,y:delta*delta*(Math.abs(x/delta)-Math.log1p(Math.abs(x/delta)))})); const sx=x=>170+x*45,sy=y=>190-Math.min(y,3.2)*48; $: path=curve.map((p,i)=>`${i?'L':'M'}${sx(p.x)} ${sy(p.y)}`).join(' ');
</script>
<div class="lesson-grid" data-part4-fair-regularizer data-focus={lesson.focus}><section class="panel"><p class="eyebrow">Fair potential · exact-ID</p><svg viewBox="0 0 340 220" role="img" aria-label="Fair potential curve"><line class="axis" x1="20" y1="190" x2="320" y2="190"/><line class="axis" x1="170" y1="20" x2="170" y2="205"/><path class="curve" d={path}/></svg><label>δ <output>{f(delta,2)}</output><input bind:value={delta} type="range" min=".3" max="2.5" step=".05"/></label><div class="metrics"><div><span>Lψ</span><strong>{f(result.potentialLipschitzConstant)}</strong></div><div><span>max ψ̈ samples</span><strong>{f(Math.max(...result.ddpsi))}</strong></div><div><span>||C||₂²</span><strong>{f(result.cNormSq)}</strong></div><div><span>L∇R upper</span><strong>{f(result.gradLipschitzBound)}</strong></div></div></section><section class="panel"><p class="eyebrow">Cᵀψ̇(Cx) · shared computation</p><div class="table-wrap"><table><thead><tr><th>j</th><th>[Cx]j</th><th>ψ</th><th>ψ̇</th><th>ψ̈</th></tr></thead><tbody>{#each result.u as value,i (i)}<tr><td>{i+1}</td><td>{f(value)}</td><td>{f(result.psi[i])}</td><td>{f(result.dpsi[i])}</td><td>{f(result.ddpsi[i])}</td></tr>{/each}</tbody></table></div><p class="vector">∇R=[{result.grad.map(v=>f(v,3)).join(', ')}]</p><p class="note">Source blanks 041/043–046 stay distinct from completions 193–196. ψ̈≤1: <strong>{result.curvatureBoundHolds?'PASS':'FAIL'}</strong>.</p></section></div>
<style>.lesson-grid{display:grid;grid-template-columns:1fr 1fr;gap:.8rem}.panel{border:1px solid var(--color-border);border-radius:1rem;background:var(--color-background);padding:1rem}.eyebrow{margin:0 0 .5rem;font-size:.66rem;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--color-muted-foreground)}svg{width:100%;max-height:14rem}.axis{stroke:var(--color-border)}.curve{fill:none;stroke:var(--color-primary);stroke-width:3}label{display:grid;grid-template-columns:1fr auto;font-size:.72rem;font-weight:800}input{grid-column:1/-1;min-height:30px}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:.4rem;margin-top:.5rem}.metrics div{display:grid;background:var(--color-muted);border-radius:.65rem;padding:.55rem;font-size:.72rem}.metrics span{color:var(--color-muted-foreground)}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:.7rem}th,td{padding:.4rem;border-bottom:1px solid var(--color-border);text-align:right}.vector{font-family:ui-monospace,monospace;font-size:.74rem}.note{font-size:.73rem;line-height:1.65;color:var(--color-muted-foreground)}@media(max-width:760px){.lesson-grid{grid-template-columns:1fr}}</style>
